/**
 * Golden contract for the SM-18 priority-queue port (sm18-re gitlab issue #32).
 *
 * The reference lives in `sm18-re:smfmt/sub.py` + `smfmt/info_subs.py` +
 * `smfmt/element_info.py`. The fixture
 * `test/fixtures/sm18-port-priority-queue.json` is a byte-exact mirror of
 * `sm18-re:tests/fixtures/port-priority-queue.json` and is regenerated by
 * `sm18-re:scripts/export-port-priority-queue-fixture.py`. The lane re-copies
 * the mirror on every change so sm18-re's gate catches drift on either side.
 *
 * This file is brief-writer owned (gitlab issue #32). The lane implements
 * `src/sm18-priority-queue.ts` with four exports:
 *
 *   - `parseSub(data: Uint8Array): number[]`
 *   - `queuePositions(data: Uint8Array): Map<number, number>`
 *   - `liveElementNumbers(records: ElementRecord[]): number[]`
 *   - `deletedElementNumbers(records: ElementRecord[]): number[]`
 *
 * `parseSub` and `queuePositions` are the TypeScript twins of
 * `smfmt.sub.parse_sub` and `smfmt.info_subs.queue_positions`: `.sub` files
 * are headerless little-endian uint32 arrays of 1-based element numbers,
 * position 0 being the high-priority end (defended in
 * `sm18-re:docs/findings/info_subs.md`). The partition helpers split element
 * records on `element_status`: status 3 is Deleted, everything else is live,
 * and `set(parseSub(priority.sub)) == set(live)` is a priority.sub
 * invariant the fixture pins.
 *
 * Until the module exists every case `t.skip`s, so `npm test` stays green;
 * the sm18-re side gate separately checks the module file is present and
 * requires the suite to run with zero skips.
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";

const FIXTURE_PATH = join(__dirname, "fixtures", "sm18-port-priority-queue.json");
const MODULE_SPEC = ["..", "src", "sm18-priority-queue.ts"].join("/");

interface ElementRecord {
  element_number: number;
  element_type: number;
  element_status: number;
  ordinal_hex: string;
}

interface SubsetEntry {
  sub_hex: string;
  expected_order: number[];
}

interface Fixture {
  schema: number;
  source: string;
  collection: string;
  priority_sub_hex: string;
  subsets: Record<string, SubsetEntry>;
  elements: ElementRecord[];
  expected: {
    priority_queue_order: number[];
    queue_positions: Record<string, number>;
    live_element_numbers: number[];
    deleted_element_numbers: number[];
    live_matches_priority_set: boolean;
  };
}

interface PortModule {
  parseSub: (data: Uint8Array) => number[];
  queuePositions: (data: Uint8Array) => Map<number, number>;
  liveElementNumbers: (records: ElementRecord[]) => number[];
  deletedElementNumbers: (records: ElementRecord[]) => number[];
}

async function loadPort(): Promise<PortModule | null> {
  try {
    const mod = await import(MODULE_SPEC);
    if (
      typeof mod?.parseSub !== "function" ||
      typeof mod?.queuePositions !== "function" ||
      typeof mod?.liveElementNumbers !== "function" ||
      typeof mod?.deletedElementNumbers !== "function"
    ) {
      return null;
    }
    return mod as PortModule;
  } catch {
    return null;
  }
}

function hexToBytes(hex: string): Uint8Array {
  if (hex.length % 2 !== 0) {
    throw new Error(`odd-length hex: ${hex.length}`);
  }
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = parseInt(hex.substr(i * 2, 2), 16);
  }
  return out;
}

function sortedCopy(values: number[]): number[] {
  return [...values].sort((a, b) => a - b);
}

const fixture: Fixture = JSON.parse(readFileSync(FIXTURE_PATH, "utf8"));

test("fixture is present and non-empty", () => {
  assert.equal(fixture.schema, 1);
  assert.ok(fixture.priority_sub_hex.length > 0, "fixture has priority.sub bytes");
  assert.ok(
    Object.keys(fixture.subsets).length >= 1,
    "fixture has at least one subset",
  );
  assert.ok(fixture.elements.length > 0, "fixture has element records");
  assert.ok(
    fixture.expected.priority_queue_order.length > 0,
    "fixture has a non-empty priority queue",
  );
});

test("src/sm18-priority-queue.ts exports the four port functions", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("src/sm18-priority-queue.ts not implemented yet");
    return;
  }
  assert.equal(typeof port.parseSub, "function");
  assert.equal(typeof port.queuePositions, "function");
  assert.equal(typeof port.liveElementNumbers, "function");
  assert.equal(typeof port.deletedElementNumbers, "function");
});

test("parseSub reproduces priority.sub order", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("src/sm18-priority-queue.ts not implemented yet");
    return;
  }
  const bytes = hexToBytes(fixture.priority_sub_hex);
  const got = port.parseSub(bytes);
  assert.deepEqual(got, fixture.expected.priority_queue_order);
});

for (const [name, subset] of Object.entries(fixture.subsets)) {
  test(`parseSub reproduces subsets/${name} order`, async (t) => {
    const port = await loadPort();
    if (port === null) {
      t.skip("src/sm18-priority-queue.ts not implemented yet");
      return;
    }
    const bytes = hexToBytes(subset.sub_hex);
    const got = port.parseSub(bytes);
    assert.deepEqual(got, subset.expected_order);
  });
}

test("queuePositions matches the Python reference", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("src/sm18-priority-queue.ts not implemented yet");
    return;
  }
  const bytes = hexToBytes(fixture.priority_sub_hex);
  const got = port.queuePositions(bytes);
  const expected = fixture.expected.queue_positions;
  assert.equal(
    got.size,
    Object.keys(expected).length,
    `queue size: got ${got.size}, want ${Object.keys(expected).length}`,
  );
  for (const [idStr, pos] of Object.entries(expected)) {
    const id = Number(idStr);
    assert.equal(got.get(id), pos, `queue_positions[${id}] mismatch`);
  }
});

test("liveElementNumbers partition matches", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("src/sm18-priority-queue.ts not implemented yet");
    return;
  }
  const got = sortedCopy(port.liveElementNumbers(fixture.elements));
  assert.deepEqual(got, fixture.expected.live_element_numbers);
});

test("deletedElementNumbers partition matches", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("src/sm18-priority-queue.ts not implemented yet");
    return;
  }
  const got = sortedCopy(port.deletedElementNumbers(fixture.elements));
  assert.deepEqual(got, fixture.expected.deleted_element_numbers);
});

test("priority.sub set equals live set (invariant)", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("src/sm18-priority-queue.ts not implemented yet");
    return;
  }
  const bytes = hexToBytes(fixture.priority_sub_hex);
  const prioritySorted = sortedCopy(port.parseSub(bytes));
  const liveSorted = sortedCopy(port.liveElementNumbers(fixture.elements));
  assert.deepEqual(prioritySorted, liveSorted);
  assert.equal(
    fixture.expected.live_matches_priority_set,
    true,
    "fixture asserts the invariant holds in the ABC sample",
  );
});
